META={'id':'g8-ma-hl-a','subj':'數學','name':'八上 數學 翰林 A卷','source':'翰林版 八年級數學（三）A卷（114上，教用版答案與解析；僅收選擇題）'}

sec('第1回 1-1 乘法公式')
ch(r'下列三個等式，正確的有哪些？(甲) \((49-39)^2=49^2-2\times49\times39-39^2\)；(乙) \((29+39)^2=29^2+39^2\)；(丙) \((39-29)^2=39^2-29^2\)',['僅(甲)','(乙)(丙)','(甲)(乙)(丙)','(甲)(乙)(丙)皆錯誤'],4,r'(甲) \((49-39)^2=49^2-2\times49\times39+39^2\)；(乙) \((29+39)^2=29^2+2\times29\times39+39^2\)；(丙) \((39-29)^2=39^2-2\times39\times29+29^2\)，故選(D)。')
ch(r'計算 \((119-74)^2\) 的結果，與下列哪一個式子相同？',[r'\(119^2-74^2\)',r'\((119-74)(119+74)\)',r'\(119^2-2\times119\times74-74^2\)',r'\(119^2-2\times119\times74+74^2\)'],4,r'\((119-74)^2=119^2-2\times119\times74+74^2\)。')
ch(r'【素養】計算 \((505+1.23+2.27)^2-(505-1.23-2.27)^2\) 之值為何？',['4040','5050','7070','9090'],3,r'原式＝\([(505+1.23+2.27)+(505-1.23-2.27)]\times[(505+1.23+2.27)-(505-1.23-2.27)]=1010\times7=7070\)。')
ch(r'【素養】利用乘法公式求出 \(995^2\) 與 \(1005^2\) 這兩個數哪一個比較接近 \(1000^2\)？',[r'\(995^2\)',r'\(1005^2\)','兩者一樣','無法判斷'],1,r'\(1000^2-995^2=(1000+995)(1000-995)=1995\times5\)；\(1005^2-1000^2=(1005+1000)(1005-1000)=2005\times5\)；因為 \(1000^2-995^2<1005^2-1000^2\)，故選(A)。')
ch(r'【素養】計算 \(\left(23\dfrac{11}{17}\right)^2+23\dfrac{11}{17}\times\dfrac{12}{17}+\left(\dfrac{6}{17}\right)^2\) 之值為何？',['529','549','576','596'],3,r'原式＝\(\left(23\dfrac{11}{17}\right)^2+2\times23\dfrac{11}{17}\times\dfrac{6}{17}+\left(\dfrac{6}{17}\right)^2=\left(23\dfrac{11}{17}+\dfrac{6}{17}\right)^2=24^2=576\)。')
ch(r'【素養】算式 \(2019\times\left(-\dfrac{2021}{2020}\right)\) 的值最接近下列哪一個數？',['－2021','－2020','－2019','－2018'],2,r'原式＝\(2019\times\left(-1-\dfrac{1}{2020}\right)=-2019-\dfrac{2019}{2020}\approx-2020\)。')
ch(r'【素養】若 \(a+b=5\)，\(ab=3\)，則 \(a^2+b^2\) 之值為何？',['17','18','19','20'],3,r'\((a+b)^2=a^2+2ab+b^2\Rightarrow5^2=a^2+2\times3+b^2\Rightarrow a^2+b^2=25-6=19\)。')
ch(r'【素養】附圖為兩個邊長分別為 \(a\)、\(b\) 的正方形的重疊情形，則塗色部分的面積與下列哪一個選項的面積相同？',[r'長、寬分別為 \(a+b\)、\(a-b\) 的長方形',r'邊長為 \(a-b\) 的正方形',r'底為 \(a+b\)，其對應高為 \(a-b\) 的三角形',r'上底為 \(a\)、下底為 \(b\)、高為 \(a-b\) 的梯形'],1,r'塗色部分面積＝\(a^2-b^2\)；(A) \((a+b)(a-b)=a^2-b^2\)。',img=(1,425,1375,510,1460))
psg('如附圖，已知公布欄的長為426公分，寬為142公分，小美將此公布欄分成三等分，並將每等分都貼上邊框，其中邊框設定為2公分，且每等分的上、下兩角落均各黏上一個腰長為2公分的等腰直角三角形，剩餘灰色部分則用來分別張貼榮譽榜、重要公告、課表等訊息。【素養題】')
ch('【素養】請問邊框部分所占的面積為多少平方公分？',['3312','3360','3408','3564'],2,r'\(426\div3=142\)，\(142^2-138^2=(142+138)(142-138)=280\times4=1120\)，所求＝\(1120\times3=3360\)（平方公分）。',img=(1,600,585,895,705))
ch('【素養】請問公布欄張貼各種訊息的灰色部分總面積為多少平方公分？',['55620','56820','57000','57120'],4,r'\(138^2-2^2=(138+2)(138-2)=140\times136=(140)(140-4)=19600-560=19040\)，所求＝\(19040\times3=57120\)（平方公分）。',img=(1,600,585,895,705))
endp()

sec('第2回 1-2 多項式的加減')
ch(r'下列哪些是多項式？(甲) \(5x-3+4x^2\)；(乙) \(7x^2+|x-3|\)；(丙) \(\dfrac{5}{x}+3\)；(丁) \(\dfrac{x}{5}+4\)',['(甲)(乙)','(甲)(丁)','(甲)(乙)(丙)','(甲)(丙)(丁)'],2,r'(乙) \(x\) 出現在絕對值內；(丙) \(x\) 出現在分母，均不是多項式，故選(B)。')
ch(r'若多項式 \(A\)、\(B\) 均為 \(x\) 的二次多項式，則 \(A+B\) 的次數不可能為幾次？',['零次','一次','二次','三次'],4,r'\(A+B\) 的次數可能為二次、一次或零次，故選(D)。')
ch(r'【素養】已知一長方形的長、寬分別為 \(3x^2-x+7\)、\(5x^2-3x-4\)，則此長方形的周長為何？',[r'\(16x^2+8x+6\)',r'\(16x^2+4x-6\)',r'\(16x^2-8x+6\)',r'\(8x^2-4x+3\)'],3,r'周長＝\(2[(3x^2-x+7)+(5x^2-3x-4)]=2(8x^2-4x+3)=16x^2-8x+6\)。')
ch(r'【素養】計算 \((x^2-x-1)-[2x^2-x+4+(2x^2-1)]\) 之值為何？',[r'\(-3x^2+4\)',r'\(-3x^2-4\)',r'\(3x^2+4\)',r'\(3x^2-4\)'],2,r'原式＝\(x^2-x-1-2x^2+x-4-2x^2+1=-3x^2-4\)。')
ch(r'【素養】已知 \(a\)、\(b\)、\(c\) 皆為整數，且滿足 \(|a-1|+2|b+1|+3|c|=1\)，則 \(ax^3+bx^2+cx+d\) 為 \(x\) 的幾次多項式？',['必為三次多項式','必為二次多項式','為三次或二次多項式','為三次或一次多項式'],3,r'滿足條件則 \(|a-1|=1\)，\(b+1=0\)，\(c=0\Rightarrow a=2\) 或 \(0\)，\(b=-1\)，\(c=0\)；\(a=2\) 時為三次多項式，\(a=0\) 時為二次多項式，故選(C)。')
ch(r'【素養】\(5x^3-2x^2+4x-3\) 與 \(3x^2-6x+2\) 的和加上下列哪一個式子後會等於 0？',[r'\(5x^3+x^2-2x+1\)',r'\(5x^3+x^2-2x-1\)',r'\(-5x^3-x^2+2x+1\)',r'\(-x^2+4x-2\)'],3,r'設所求為 \(A\)，\(5x^3-2x^2+4x-3+3x^2-6x+2+A=0\Rightarrow5x^3+x^2-2x-1+A=0\Rightarrow A=-5x^3-x^2+2x+1\)。')
ch(r'【素養】在 \(x\) 的多項式 \(ax^2-x-a\) 與 \(-3x^2+2ax+5\) 的和中，若常數項為 \(b\)，\(x^2\) 項係數為 \(-1\)，則 \(a-b\) 之值為何？',['2','1','－1','－2'],3,r'\(ax^2-x-a+(-3x^2+2ax+5)=(a-3)x^2+(2a-1)x+(5-a)\Rightarrow a-3=-1\)，\(5-a=b\Rightarrow a=2\)，\(b=3\)，故 \(a-b=2-3=-1\)。')
ch(r'【素養】甲、乙、丙三人計算 \((3x^2+8x+2)-(ax^2+bx+c)\) 得到的答案分別為 \(6x^2+10x-1\)、\(6x-1\)、\(-6x^2+10x+5\)。若甲只答對 \(x^2\) 項，乙只答對 \(x\) 項，丙只答對常數項，則下列選項何者正確？',[r'\(a=c\)',r'\(a+b=1\)',r'\(b+c=1\)',r'\(a+b+c=4\)'],1,r'依題意知：\((3x^2+8x+2)-(ax^2+bx+c)=6x^2+6x+5\)，\(ax^2+bx+c=(3x^2+8x+2)-(6x^2+6x+5)=-3x^2+2x-3\Rightarrow a=-3\)，\(b=2\)，\(c=-3\)，故選(A)。')
psg(r'老師想了解學生對多項式運算的學習狀況，抽選幾位同學上臺答題，如附圖所示（黑板：有多項式 \(A\) 和 \(B\)，其中 \(A=x^2-5x+9\)，\(A+B=3x^2+4\)，求多項式 \(B\)＝？）。【素養題】')
ch('【素養】老師請小花先答題，若小花回答正確，則小花的答案為何？',[r'\(2x^2-5x+5\)',r'\(2x^2+5x-5\)',r'\(2x^2-5x-5\)',r'\(2x^2+5x+5\)'],2,r'\(B=3x^2+4-(x^2-5x+9)=2x^2+5x-5\)。',img=(3,615,745,945,880))
ch(r'【素養】老師進一步請阿福計算 \(2A-B\)，但阿福卻誤算成 \(2A+B\)，除此之外沒有其他錯誤。請問阿福誤算的答案與 \(2A-B\) 的正確答案相差多少？',[r'\(8x-5\)',r'\(x^2-3x+5\)',r'\(4x^2-3x+2\)',r'\(4x^2+10x-10\)'],4,r'\((2A+B)-(2A-B)=2B=2(2x^2+5x-5)=4x^2+10x-10\)。',img=(3,615,745,945,880))
endp()

sec('第3回 1-3 多項式的乘除')
ch(r'若 \(6x^2+3x+2\) 除以 \(3x\) 的商式為 \(A\)，餘式為 \(B\)，則 \(A+B\)＝？',[r'\(2x+1\)',r'\(2x+2\)',r'\(2x+3\)',r'\(2x+4\)'],3,r'\((6x^2+3x+2)\div3x\) 的商式為 \(2x+1\)，餘式為 2 \(\Rightarrow A=2x+1\)，\(B=2\)，故 \(A+B=2x+1+2=2x+3\)。')
ch(r'若 \((x+10)(x-3)=x^2+ax+b\)，則 \(a-b\) 之值為何？',['－37','－23','23','37'],4,r'\((x+10)(x-3)=x^2+7x-30\Rightarrow a=7\)，\(b=-30\)，故 \(a-b=7-(-30)=37\)。')
ch(r'【素養】若 \(A\) 為 \(x\) 的二次多項式，\(B\) 為 \(x\) 的一次多項式，\(C\) 為 \(x\) 的一次多項式，則 \((A-B)\div C\) 的商式為 \(x\) 的幾次多項式？',['四','三','二','一'],4,r'\(A-B\) 為 \(x\) 的二次多項式，\((A-B)\div C\) 的商式為 \(x\) 的一次多項式。')
ch(r'【素養】求 \([(2x^2+x-3)-(-x^2-3x+4)]\div(x-1)\) 的商式為何？',[r'\(3x-7\)',r'\(3x+7\)',r'\(x-1\)',r'\(x+1\)'],2,r'\((2x^2+x-3)-(-x^2-3x+4)=3x^2+4x-7\)，以長除法除以 \(x-1\)，故商式為 \(3x+7\)。')
ch('【素養】下列選項何者正確？',[r'\(2x^2\div(-x)=2x\)',r'\(4x^2\div(-2x)^2=-2\)',r'\((-25x^2)\div5x=-5x\)',r'\((4x^2+6x)\div(-2x)=-2x+3\)'],3,r'(A) \(2x^2\div(-x)=-2x\)；(B) \(4x^2\div(-2x)^2=4x^2\div4x^2=1\)；(D) \((4x^2+6x)\div(-2x)=-2x-3\)。')
ch(r'【素養】若 \([(2x+3)-(5x-2)]^2=ax^3+bx^2+cx+d\)，則 \(a+b+c+d\) 之值為何？',['64','4','－4','－64'],2,r'\([(2x+3)-(5x-2)]^2=(-3x+5)^2=9x^2-30x+25\)，\(a=0\)，\(b=9\)，\(c=-30\)，\(d=25\)，\(a+b+c+d=0+9+(-30)+25=4\)。')
ch(r'【素養】\(A\)、\(B\) 為兩多項式，且 \(4A=-4x^2+3x-8\)，\(3B=8x^2-5x-4\)，則 \(A\times B\) 的常數項為何？',['－1',r'\(-\dfrac{3}{8}\)',r'\(\dfrac{8}{3}\)','32'],3,r'\(4A\times3B\) 的常數項＝\((-8)\times(-4)=32\Rightarrow12(A\times B)\) 的常數項＝32 \(\Rightarrow A\times B\) 的常數項＝\(\dfrac{32}{12}=\dfrac{8}{3}\)。')
ch(r'【素養】附圖是小蕾利用直式除法求出 \((x^2-6x)\div(x-3)\) 的商式與餘式的過程與結果，判斷下列哪一個式子是錯誤的？',[r'\((x^2-6x)\div(x-3)=(x-3)-9\)',r'\(x^2-6x=(x-3)(x-3)-9\)',r'\(x^2-6x=(x-3)^2-9\)',r'\((x^2-6x+9)\div(x-3)=x-3\)'],1,r'\((x^2-6x)\div(x-3)=x-3\cdots\)餘 \(-9\)，故選(A)。',img=(5,880,330,1000,452))
psg(r'某工廠製作的畫框如附圖所示，此畫框為長方形，其長為 \((2x+5)\) 公分，寬為 \((x+7)\) 公分，邊框的寬度均為 2 公分。【素養題】')
ch('【素養】若不計厚度，則此畫框的邊框面積為多少平方公分？',[r'\(12x+32\)',r'\(12x+48\)',r'\(6x+16\)',r'\(6x+24\)'],1,r'所求＝\((2x+5)(x+7)-(2x+1)(x+3)=(2x^2+19x+35)-(2x^2+7x+3)=12x+32\)（平方公分）。',img=(5,830,630,995,766))
ch('【素養】若工廠為節省材料，欲將邊框的寬度縮減為原來的一半，則省下的邊框面積為多少平方公分？',[r'\(3x+4\)',r'\(3x+6\)',r'\(6x+8\)',r'\(6x+12\)'],4,r'所求＝\((2x+3)(x+5)-(2x+1)(x+3)=(2x^2+13x+15)-(2x^2+7x+3)=6x+12\)（平方公分）。',img=(5,830,630,995,766))
endp()

sec('第4回 2-1 平方根的意義')
ch(r'計算 \(\sqrt{5\dfrac{4}{9}}\) 之值為何？',[r'\(\dfrac{2}{3}\)',r'\(\pm\dfrac{2}{3}\)',r'\(\dfrac{7}{3}\)',r'\(\pm\dfrac{7}{3}\)'],3,r'\(\sqrt{5\dfrac{4}{9}}=\sqrt{\dfrac{49}{9}}=\sqrt{\left(\dfrac{7}{3}\right)^2}=\dfrac{7}{3}\)。')
ch(r'下列四個數中，有多少個數的值會相等？\(\sqrt{\dfrac{9}{16}}\)、\(\sqrt{\left(\dfrac{3}{4}\right)^2}\)、\(\sqrt{\dfrac{3^2}{4^2}}\)、\(\sqrt{\left(-\dfrac{3}{4}\right)^2}\)',['0','2','3','4'],4,r'四個數都等於 \(\dfrac{3}{4}\)，故選(D)。')
ch(r'【素養】計算 \(\sqrt{(12.8)^2-2\times12.8\times3.5+(3.5)^2}\) 之值為何？',['9.3','9.5','16.3','16.5'],1,r'原式＝\(\sqrt{(12.8-3.5)^2}=9.3\)。')
ch('【素養】下列有關平方根的敘述，何者正確？',['因為沒有任何整數的平方等於 3，所以 3 沒有平方根',r'已知 \(a=3^2\)，所以 \(a\) 是 3 的平方根',r'因為 \(-3^2=-9\)，所以 \(-3\) 是 \(-9\) 的平方根',r'已知 \(a\) 是 3 的平方根，所以 \(-a\) 也是 3 的平方根'],4,r'(A) 3 的平方根為 \(\pm\sqrt{3}\)；(B) 3 是 \(a\) 的平方根；(C) \((-3)^2=9\)，\(-3\) 是 9 的平方根。')
ch(r'【素養】下列有關 \(\sqrt{10}\) 的敘述，何者錯誤？',[r'在數線上可以找到坐標為 \(\sqrt{10}\) 的點',r'\((\sqrt{10})^2=10\)',r'\(\sqrt{10}=5\)',r'\(\sqrt{10}<4\)'],3,r'(C) \(5=\sqrt{25}\neq\sqrt{10}\)。')
ch('【素養】下列敘述何者正確？',[r'\(\sqrt{(-5)^2}=-5\)',r'若 \(a\geq0\)，則 \(\sqrt{a^2}=a\)','任意數之平方根皆有兩個值',r'因為 2、\(-2\) 皆為 4 的平方根，所以 \(\sqrt{4}=\pm2\)'],2,r'(A) \(\sqrt{(-5)^2}=5\)；(C) 0 的平方根只有 0；(D) \(\sqrt{4}=2\)。')
ch(r'【素養】已知 \(\sqrt{120\times b}\) 是正整數，則 \(b\) 的最小值為何？',['12','15','24','30'],4,r'\(\because\sqrt{120\times b}\) 是正整數，且 \(120=2^3\times3\times5\)，故所求＝\(2\times3\times5=30\)。')
ch(r'【素養】下列敘述哪些正確？(甲) \(\sqrt{81}\) 的平方根為 \(\pm9\)；(乙) \(\sqrt{\dfrac{12}{75}}=\dfrac{2}{5}\)；(丙) \(\sqrt{(\sqrt{3}-3)^2}=3-\sqrt{3}\)；(丁) 若 \(x^2=2\)，則 \(x=\sqrt{2}\)',['(甲)(乙)','(乙)(丙)','(丙)(丁)','(甲)(丁)'],2,r'(甲) \(\sqrt{81}=9\)，9 的平方根＝\(\pm3\)；(乙) \(\sqrt{\dfrac{12}{75}}=\sqrt{\dfrac{4}{25}}=\dfrac{2}{5}\)；(丙) \(\sqrt{(\sqrt{3}-3)^2}=|\sqrt{3}-3|=3-\sqrt{3}\)；(丁) 若 \(x^2=2\)，則 \(x=\pm\sqrt{2}\)，故選(B)。')
psg(r'計算機上 [√]、[1/x]、[x²] 三個按鍵，其功能說明如下：[√]：將螢幕顯示的數變成它的正平方根，例如：螢幕顯示的數為 36，按下 [√] 會變成 6。[1/x]：將螢幕顯示的數變成它的倒數，例如：螢幕顯示的數為 4，按下 [1/x] 會變成 0.25。[x²]：將螢幕顯示的數變成它的平方，例如：螢幕顯示的數為 2，按下 [x²] 會變成 4。【素養題】')
ch('【素養】若螢幕顯示的數為 25，小妤依序按下 [√]、[1/x]、[x²]，則最後螢幕顯示的數為何？',['0.04','0.05','0.4','0.5'],1,r'\(25\rightarrow5\rightarrow0.2\rightarrow0.04\)。')
ch('【素養】若螢幕顯示某數，小強第一下按 [√]，第二下按 [1/x]，第三下按 [x²]，之後以 [√]、[1/x]、[x²] 的順序輪流按，當他按了第 100 下後螢幕顯示的數為 0.1，則一開始螢幕所顯示的某數為何？',['0.01','0.1','10','100'],4,r'設一開始的數為 \(x\)，則依序為 \(x\rightarrow\sqrt{x}\rightarrow\dfrac{1}{\sqrt{x}}\rightarrow\dfrac{1}{x}\rightarrow\dfrac{1}{\sqrt{x}}\rightarrow\sqrt{x}\rightarrow x\rightarrow\cdots\)，每按 6 下一循環；\(100\div6=16\cdots\)餘 4，故 \(\dfrac{1}{\sqrt{x}}=0.1\Rightarrow x=100\)。')
endp()

sec('第5回 1-1～2-1 複習')
ch(r'計算 \(328\times0.64-18\times0.64+328\times0.36-18\times0.36\) 之值為何？',['328','310','300','1'],2,r'原式＝\(328\times(0.64+0.36)-18\times(0.64+0.36)=328\times1-18\times1=310\)。')
ch('關於多項式乘法的計算，下列何者正確？',[r'\((13x-7)^2=169x^2-91x+49\)',r'\((2x+3)^2=4x^2+9\)',r'\((5+x)(-x-1)=-x^2+6x-5\)',r'\((-4x+3)^2=16x^2-24x+9\)'],4,r'(A) 原式＝\(169x^2-182x+49\)；(B) 原式＝\(4x^2+12x+9\)；(C) 原式＝\(-x^2-6x-5\)。')
ch(r'【素養】若 \(a(x^2+2x-1)+b(x^2+3)+x-5\) 中，\(x^2\) 項及 \(x\) 項係數都是 0，則下列選項何者錯誤？',[r'\(a=-\dfrac{1}{2}\)',r'\(b=\dfrac{1}{2}\)','常數項為 －3','各項係數總和為 3'],4,r'原式＝\((a+b)x^2+(2a+1)x+(-a+3b-5)\)，\(a+b=0\)，\(2a+1=0\Rightarrow a=-\dfrac{1}{2}\)，\(b=\dfrac{1}{2}\)；常數項＝\(-\left(-\dfrac{1}{2}\right)+3\times\dfrac{1}{2}-5=-3\)；各項係數總和＝常數項＝－3，故選(D)。')
ch(r'【素養】\(a\)、\(b\)、\(c\) 為三個連續的奇數，則 \(b^2\) 與 \(a\times c\) 之值相差多少？',['4','6','9','視三數的值而定，沒有一定的答案'],1,r'設 \(a=x-2\)，\(b=x\)，\(c=x+2\)，所求＝\(|x^2-(x-2)(x+2)|=|x^2-(x^2-4)|=4\)。')
ch('【素養】下列哪一個選項的值最小？',[r'\(-(\sqrt{0.6})^2\)',r'\((-\sqrt{3.6})^2\)',r'\(\sqrt{(-1.3)^2}\)',r'\(\dfrac{1}{\sqrt{3}}\)'],1,r'(A) \(-0.6\)；(B) 3.6；(C) 1.3；(D) \(0<\dfrac{1}{\sqrt{3}}<1\)，故選(A)。')
ch(r'【素養】若 \((-6x^2-8x+15)\div(3x-2)\) 的商式為 \(ax+b\)，餘式為 \(c\)，則 \(a+b+c\) 之值為何？',['－9','－5','1','13'],3,r'\((-6x^2-8x+15)\div(3x-2)\) 的商式為 \(-2x-4\)，餘式為 7，\(a=-2\)，\(b=-4\)，\(c=7\)，故 \(a+b+c=(-2)+(-4)+7=1\)。')
ch(r'【素養】已知 \(A\)、\(B\) 皆為 \(x\) 的三次多項式，且多項式 \(A=ax^3+bx^2+cx+d\)，多項式 \(B=mx^3-nx^2-hx-k\)。若 \(A-B=x-1\)，則下列敘述何者正確？',[r'\(a+m=0\)',r'\(b+n=0\)',r'\(c+h=-1\)',r'\(d+k=1\)'],2,r'\(A-B=(a-m)x^3+(b+n)x^2+(c+h)x+(d+k)=x-1\)，\(a-m=0\)，\(b+n=0\)，\(c+h=1\)，\(d+k=-1\)，故選(B)。')
ch(r'【素養】已知 \(a\) 為小於 60 的正整數，若 \(\sqrt{18a}\) 是正整數，則滿足此條件的 \(a\) 值共有多少個？',['3','4','5','6'],3,r'\(18=2\times3^2\)，\(a=2\times n^2\) 才為正整數，故 \(a=2\)、8、18、32、50，共 5 個。')
psg('計算機上有按鍵 [√]，其表示把螢幕顯示的數變成它的正平方根。例如：螢幕顯示的數為 16，按下 [√] 變成 4。【素養題】')
ch('【素養】若螢幕顯示的數為 19，小強按下 [√] 後得到 4.3588989，則下列敘述何者正確？',[r'\((4.3588989)^2\) 的值等於 19',r'\(4.35<\sqrt{19}<4.36\)',r'\(\sqrt{19}\) 比 4.3589 大',r'\(\sqrt{19}\) 比 4.3588 小'],2,r'\(4.35<4.3588989<4.36\)，故選(B)。')
ch('【素養】若螢幕顯示的數為 63504，小明按下 [√] 後，會得到下列何者？',['168','228','252','258'],3,r'\(63504=2^4\times3^4\times7^2\)，故 \(\sqrt{63504}=2^2\times3^2\times7=252\)。')
endp()

sec('第6回 2-2 根式的運算')
ch(r'下列根式的運算，正確的有哪些？(甲) \(\sqrt{2}+\sqrt{10}=\sqrt{12}\)；(乙) \(\sqrt{13}-\sqrt{8}=\sqrt{5}\)；(丙) \(\sqrt{3}\times\sqrt{5}=\sqrt{15}\)；(丁) \(\sqrt{14}\div\sqrt{2}=\sqrt{7}\)',['(甲)(乙)','(甲)(丙)','(乙)(丁)','(丙)(丁)'],4,r'(甲) \(\sqrt{2}+\sqrt{10}\neq\sqrt{12}\)；(乙) \(\sqrt{13}-\sqrt{8}\neq\sqrt{5}\)；(丙) \(\sqrt{3}\times\sqrt{5}=\sqrt{15}\)；(丁) \(\sqrt{14}\div\sqrt{2}=\sqrt{7}\)，故選(D)。')
ch('下列哪一個算式的值最大？',[r'\(\sqrt{\dfrac{5}{3}}\div\sqrt{\dfrac{25}{3}}\times\sqrt{\dfrac{5}{2}}\div\sqrt{\dfrac{9}{4}}\)',r'\(\sqrt{24}\div\sqrt{8}\times\sqrt{3}\)',r'\(\sqrt{(-4)^2}\)',r'\(\sqrt{13^2-12^2}\)'],4,r'(A) 原式＝\(\sqrt{\dfrac{2}{9}}=\dfrac{\sqrt{2}}{3}\)；(B) 原式＝\(\sqrt{9}=3\)；(C) 原式＝4；(D) 原式＝\(\sqrt{25}=5\)，故選(D)。')
ch(r'【素養】解方程式 \((\sqrt{5}+1)x=4\)，得 \(x\)＝？',['1','2',r'\(\sqrt{5}-1\)',r'\(\dfrac{2}{3}(\sqrt{5}+1)\)'],3,r'\(x=\dfrac{4}{\sqrt{5}+1}\times\dfrac{\sqrt{5}-1}{\sqrt{5}-1}=\dfrac{4(\sqrt{5}-1)}{4}=\sqrt{5}-1\)。')
ch(r'【素養】比較 \(\sqrt{2}+\sqrt{3}\) 與 \(\sqrt{5}\) 的大小關係，何者較大？',[r'\(\sqrt{2}+\sqrt{3}\)',r'\(\sqrt{5}\)','一樣大','無法比較'],1,r'\((\sqrt{2}+\sqrt{3})^2=5+2\sqrt{6}\)，\((\sqrt{5})^2=5\)，故 \(\sqrt{2}+\sqrt{3}>\sqrt{5}\)。')
ch(r'【素養】若 \(\sqrt{18}+\sqrt{98}-\sqrt{72}=\sqrt{a}\)，則 \(a\) 之值為何？',['16','32','48','64'],2,r'\(\sqrt{18}+\sqrt{98}-\sqrt{72}=3\sqrt{2}+7\sqrt{2}-6\sqrt{2}=4\sqrt{2}=\sqrt{32}\)，故 \(a=32\)。')
ch(r'【素養】計算 \((1+\sqrt{3}-\sqrt{5})(1-\sqrt{3}+\sqrt{5})\) 之值為何？',[r'\(5-2\sqrt{3}\)',r'\(7-4\sqrt{15}\)',r'\(-7+2\sqrt{15}\)',r'\(-10+3\sqrt{5}\)'],3,r'原式＝\(1^2-(\sqrt{3}-\sqrt{5})^2=1-(3-2\sqrt{15}+5)=-7+2\sqrt{15}\)。')
ch(r'【素養】\(-\sqrt{12}\) 與下列何者不是同類方根？',[r'\(\sqrt{75}\)',r'\(\sqrt{27}\)',r'\(-\sqrt{24}\)',r'\(-\sqrt{48}\)'],3,r'\(-\sqrt{12}=-2\sqrt{3}\)；\(\sqrt{75}=5\sqrt{3}\)，\(\sqrt{27}=3\sqrt{3}\)，\(-\sqrt{24}=-2\sqrt{6}\)，\(-\sqrt{48}=-4\sqrt{3}\)，故選(C)。')
ch(r'【素養】計算 \(\dfrac{9\sqrt{3}+7\sqrt{12}-5\sqrt{48}}{(\sqrt{5}+\sqrt{2})(\sqrt{2}-\sqrt{5})}\) 之值為何？',[r'\(\sqrt{3}\)',r'\(-\sqrt{3}\)','3','－3'],2,r'原式＝\(\dfrac{9\sqrt{3}+14\sqrt{3}-20\sqrt{3}}{2-5}=\dfrac{3\sqrt{3}}{-3}=-\sqrt{3}\)。')
psg('附圖是小強用電腦軟體設計的正方形與長方形圖案，已知兩個圖案的面積均為 45 平方單位。【素養題】')
ch('【素養】請問正方形的邊長為何？',[r'\(3\sqrt{3}\)',r'\(3\sqrt{5}\)',r'\(5\sqrt{3}\)',r'\(5\sqrt{5}\)'],2,r'邊長＝\(\sqrt{45}=\sqrt{3^2\times5}=3\sqrt{5}\)。',img=(11,800,515,1000,610))
ch(r'【素養】若長方形的長為 \(5\sqrt{3}\)，則長方形的寬為何？',[r'\(3\sqrt{3}\)',r'\(3\sqrt{5}\)',r'\(5\sqrt{3}\)',r'\(5\sqrt{5}\)'],1,r'\(45\div5\sqrt{3}=\dfrac{9}{\sqrt{3}}=\dfrac{9\times\sqrt{3}}{\sqrt{3}\times\sqrt{3}}=\dfrac{9\sqrt{3}}{3}=3\sqrt{3}\)。',img=(11,800,515,1000,610))
endp()

sec('第7回 2-3 畢氏定理')
ch(r'直角三角形 \(ABC\) 中，\(\overline{AB}=3\)，\(\overline{BC}=5\)，\(\overline{AC}=4\)，\(\overline{AD}\) 為斜邊上的高，則 \(\overline{AD}\)＝？',[r'\(\dfrac{6}{5}\)',r'\(\dfrac{9}{5}\)',r'\(\dfrac{12}{5}\)',r'\(\dfrac{16}{5}\)'],3,r'\(\overline{AD}=\dfrac{3\times4}{5}=\dfrac{12}{5}\)。')
ch('下列敘述何者正確？',[r'\(\sqrt{5}\)、\(\sqrt{12}\)、\(\sqrt{17}\) 為直角三角形的三邊長',r'若直角三角形的三邊長分別為 \(a\)、\(b\)、\(c\)，則 \(a^2+b^2=c^2\)',r'若直角三角形的三邊長分別為 \(3a\)、\(4b\)、\(5c\)，則 \((3a)^2+(4b)^2=(5c)^2\)','若直角三角形的兩股長分別為 7、25，則斜邊長等於 24'],1,r'(B) \(c\) 不一定是斜邊；(C) \(5c\) 不一定是斜邊；(D) 斜邊長＝\(\sqrt{7^2+25^2}=\sqrt{674}\)。')
ch('【素養】下列哪一點與坐標平面上原點的距離最遠？',['(5，－5)','(3，3.5)','(0，－7)','(－4，－6)'],4,r'(A) \(\sqrt{5^2+(-5)^2}=\sqrt{50}\)；(B) \(\sqrt{3^2+3.5^2}=\sqrt{21.25}\)；(C) \(\sqrt{0^2+(-7)^2}=\sqrt{49}\)；(D) \(\sqrt{(-4)^2+(-6)^2}=\sqrt{52}\)，故選(D)。')
ch(r'【素養】若直角三角形的三邊長為 5、12、\(x\)，則 \(x\)＝？',['13',r'\(\sqrt{119}\)',r'13 或 \(\sqrt{119}\)','無法判斷'],3,r'若 \(x\) 為斜邊，則 \(x=\sqrt{5^2+12^2}=13\)；若 12 為斜邊，則 \(x=\sqrt{12^2-5^2}=\sqrt{119}\)，故選(C)。')
ch(r'【素養】\(\triangle ABC\) 中，已知 \(\angle C=54^\circ\)，且 \(\angle A:\angle B=5:2\)，則下列何者正確？',[r'\(\overline{AB}^2+\overline{AC}^2=\overline{BC}^2\)',r'\(\overline{AB}^2+\overline{BC}^2=\overline{AC}^2\)',r'\(\overline{AC}^2+\overline{BC}^2=\overline{AB}^2\)',r'\(\overline{AB}+\overline{BC}=\overline{AC}\)'],1,r'\(\angle A+\angle B=180^\circ-54^\circ=126^\circ\)，且 \(\angle A:\angle B=5:2\Rightarrow\angle A=126^\circ\times\dfrac{5}{5+2}=90^\circ\)，故 \(\overline{AB}^2+\overline{AC}^2=\overline{BC}^2\)。')
ch(r'【素養】如附圖，四邊形 \(ABCD\) 中，\(\angle A=\angle C=90^\circ\)。若 \(\overline{BC}=\overline{CD}=5\)，\(\overline{AD}=2\)，則 \(\overline{AB}\) 長度的範圍為何？',[r'\(5<\overline{AB}<6\)',r'\(6<\overline{AB}<7\)',r'\(7<\overline{AB}<8\)',r'\(8<\overline{AB}<9\)'],2,r'連接 \(\overline{BD}\)，\(\triangle BCD\) 中，\(\overline{BD}^2=5^2+5^2=50\)；\(\triangle ABD\) 中，\(\overline{AB}^2=50-2^2=46\)，\(\overline{AB}=\sqrt{46}\)，故選(B)。',img=(13,400,1225,515,1362))
ch(r'【素養】坐標平面上有 \(A(1，3)\)、\(B(2，5)\) 兩點，則下列各組兩點間的距離何者與 \(\overline{AB}\) 不相等？',['(3，1)、(5，2)','(－1，－3)、(－2，－5)','(1＋50，3＋80)、(2＋50，5＋80)','(1×11，3×11)、(2×11，5×11)'],4,r'\(\overline{AB}=\sqrt{(2-1)^2+(5-3)^2}=\sqrt{1^2+2^2}\)；(A) \(\sqrt{2^2+1^2}\)；(B) \(\sqrt{(-1)^2+(-2)^2}\)；(C) \(\sqrt{1^2+2^2}\)；(D) \(\sqrt{11^2+22^2}\)，故選(D)。')
ch(r'【素養】如附圖，兩個正方形重疊，若正方形 \(ABDE\) 的面積為 169 平方公分，正方形 \(BCFG\) 的面積為 144 平方公分，則 \(\overline{AF}\) 的長度為多少公分？',['5','6','7','8'],3,r'\(\overline{AB}^2=\overline{AC}^2+\overline{BC}^2\Rightarrow169=\overline{AC}^2+144\Rightarrow\overline{AC}=5\)（公分），\(\overline{CF}=\sqrt{144}=12\)（公分），\(\overline{AF}=12-5=7\)（公分）。',img=(13,875,330,1000,482))
psg('附圖是陳博士發明的一款海洋探測器，只要當船隻與探測器的距離不超過 50 公里時，探測器均會發出聲音通知，今以探測器的位置為坐標平面上的原點，且單位長為 1 公里。【素養題】')
ch('【素養】若有一艘船隻位於 (35，35)，則此船隻與探測器距離多少公里？此時探測器是否會發出聲音通知？',[r'距離 \(35\sqrt{2}\) 公里，此時探測器會發出聲音通知',r'距離 \(35\sqrt{3}\) 公里，此時探測器會發出聲音通知',r'距離 \(35\sqrt{2}\) 公里，此時探測器不會發出聲音通知',r'距離 \(35\sqrt{3}\) 公里，此時探測器不會發出聲音通知'],1,r'距離＝\(\sqrt{35^2+35^2}=35\sqrt{2}\)（公里），且 \(35\sqrt{2}=\sqrt{2450}<\sqrt{2500}=50\)，故選(A)。',img=(13,860,580,1000,710))
ch('【素養】若有一艘船隻位於 (100，240)，並以時速 105 公里直線往探測器前進，且中間不停留，則幾小時後，探測器會開始發出聲音通知？',['1.5','2','2.5','3'],2,r'距離＝\(\sqrt{100^2+240^2}=260\)（公里），\(260-50=210\)，故所求＝\(210\div105=2\)（小時）。',img=(13,860,580,1000,710))
endp()

sec('第8回 3-1 提公因式與乘法公式作因式分解')
ch(r'下列多項式中，何者含有因式 \(3x-2\)？',[r'\(9x^2+4\)',r'\(3x^2-2\)',r'\(6x^2-5x-6\)',r'\(12x^2+x-6\)'],4,r'(D) \(12x^2+x-6=(3x-2)(4x+3)\)。')
ch(r'已知 \(3x^2+5x-2=(3x-1)(x+2)\)，則下列式子有哪些是 \(3x^2+5x-2\) 的因式？(甲) \(-3x+1\)；(乙) \(x-\dfrac{1}{3}\)；(丙) \(x+2\)；(丁) \(x-2\)；(戊) \(9x^2+15x-6\)；(己) 4',['(甲)(乙)(丙)','(甲)(丙)(丁)','(甲)(乙)(丙)(丁)(戊)','(甲)(乙)(丙)(戊)(己)'],4,r'(甲) \(-3x+1=-(3x-1)\)；(乙) \(x-\dfrac{1}{3}=\dfrac{1}{3}(3x-1)\)；(戊) \(\dfrac{1}{3}(9x^2+15x-6)=3x^2+5x-2\)；(己) 4（可整除任何多項式）；只有(丁)不是，故選(D)。')
ch(r'【素養】下列因式分解 \(3(x+2)(x-2)-x+2\) 的過程中，哪一個步驟開始發生錯誤？步驟一：\(3(x+2)(x-2)-(x-2)\)；步驟二：\((x-2)[3(x+2)-1]\)；步驟三：\((x-2)(3x+2-1)\)；步驟四：\((x-2)(3x+1)\)',['步驟一','步驟二','步驟三','步驟四'],3,r'步驟三：應為 \((x-2)(3x+6-1)\)，故選(C)。')
ch(r'【素養】若 \(36x^2-120x+100\) 可因式分解成 \(4(ax+b)^2\)，其中 \(a\)、\(b\) 均為整數，且 \(a>0\)，則 \(a-b\)＝？',['8','2','－2','－8'],1,r'\(36x^2-120x+100=4(9x^2-30x+25)=4(3x-5)^2\)，\(a=3\)，\(b=-5\)，\(a-b=8\)。')
ch(r'【素養】\((2x+5)^2-(5x-2)^2\) 可因式分解為下列何者？',[r'\(-(7x+3)(3x+7)\)',r'\(-(7x+3)(3x-7)\)',r'\(-3(7x+3)(3x+7)\)',r'\(-3(7x+3)(x-1)\)'],2,r'原式＝\([(2x+5)+(5x-2)][(2x+5)-(5x-2)]=(7x+3)(-3x+7)=-(7x+3)(3x-7)\)。')
ch(r'【素養】下列哪一個多項式是 \(12x^2-27\) 與 \(4x^2-12x+9\) 的公因式？',[r'\(2x^2+5x-12\)',r'\((2x-3)^2\)',r'\(2x-3\)',r'\(3x+1\)'],3,r'\(12x^2-27=3(4x^2-9)=3(2x+3)(2x-3)\)，\(4x^2-12x+9=(2x-3)^2\)，\(2x-3\) 為兩多項式的公因式。')
ch(r'【素養】有一個正方形的面積為 \([(x+1)^2-12(x+1)+36]\) 平方單位，則此正方形的邊長為下列何者？',[r'\(|x-5|\)',r'\(|x-6|\)',r'\(|x+6|\)',r'\(|x+7|\)'],1,r'\((x+1)^2-12(x+1)+36=[(x+1)-6]^2=(x-5)^2\)，故此正方形的邊長為 \(|x-5|\)。')
ch(r'【素養】已知 \((3x-2)+(3x^2-2x)\) 可因式分解為 \((3x-2)(x+a)\)，則 \(a\)＝？',['－1','0','1','2'],3,r'\((3x-2)+(3x^2-2x)=(3x-2)+x(3x-2)=(3x-2)(1+x)\)，故 \(a=1\)。')
psg(r'如附圖，小美有三種不同樣式的厚紙板，其中甲是邊長為 \(x\) 的正方形；乙是長為 \(x\)、寬為 1 的矩形；丙是邊長為 1 的正方形。【素養題】')
ch('【素養】若小美用緊密且不重疊的方式拼出圖形，則下列哪一種取法可拼出正方形？',['甲取 6 張，乙取 12 張，丙取 4 張','甲取 8 張，乙取 16 張，丙取 4 張','甲取 9 張，乙取 6 張，丙取 4 張','甲取 9 張，乙取 12 張，丙取 4 張'],4,r'(A) \(6x^2+12x+4=2(3x^2+6x+2)\)；(B) \(8x^2+16x+4=4(2x^2+4x+1)\)；(C) \(9x^2+6x+4\)；(D) \(9x^2+12x+4=(3x+2)^2\)，故選(D)。',img=(15,800,670,995,742))
ch(r'【素養】若小美取了 3 張甲，7 張乙，則小美再取幾張丙可緊密且不重疊拼出其中一邊長為 \((3x+1)\) 的長方形？',['1','2','3','4'],2,r'設再取 \(a\) 張丙，\((3x^2+7x+a)\div(3x+1)\) 的商為 \(x+2\)，餘式 \(a-2=0\Rightarrow a=2\)，故選(B)。',img=(15,800,670,995,742))
endp()

sec('第9回 3-2 利用十字交乘法因式分解')
ch(r'利用十字交乘法作 \(3x^2-2x+c\) 的因式分解，過程如附圖，則 \(c\)＝？',['－8','－4','4','8'],1,r'\(3x\) 與 \(+4\)、\(x\) 與 \(-2\) 交叉相乘：\(4x-6x=-2x\)，故 \(c=4\times(-2)=-8\)。',img=(17,415,425,510,480))
ch(r'下列何者不是 \(11a^2-22a-33\) 的因式？',[r'\(a+1\)',r'\(3-a\)',r'\(11a+33\)',r'\(-101a-101\)'],3,r'\(11a^2-22a-33=11(a^2-2a-3)=11(a+1)(a-3)\)，故選(C)。')
ch(r'【素養】下列四個多項式，哪些是 \(4x^2+21x-18\) 的因式？(甲) \(-4x+3\)；(乙) \(\dfrac{1}{6}x+1\)；(丙) \(5x+30\)；(丁) \(40x-30\)',['僅(甲)','(丙)(丁)','(甲)(丙)(丁)','(甲)(乙)(丙)(丁)'],4,r'\(4x^2+21x-18=(x+6)(4x-3)\)；(甲) \(-4x+3=-(4x-3)\)；(乙) \(\dfrac{1}{6}x+1=\dfrac{1}{6}(x+6)\)；(丙) \(5x+30=5(x+6)\)；(丁) \(40x-30=10(4x-3)\)，故選(D)。')
ch(r'【素養】若 \(481x^2+2x-3\) 可因式分解成 \((13x+a)(bx+c)\)，其中 \(a\)、\(b\)、\(c\) 均為整數，則下列敘述何者正確？',[r'\(a=1\)',r'\(b=468\)',r'\(c=-3\)',r'\(a+b+c=39\)'],4,r'\(481x^2+2x-3=(13x-1)(37x+3)\Rightarrow a=-1\)，\(b=37\)，\(c=3\)，\(a+b+c=39\)，故選(D)。')
ch(r'【素養】若 \((x-3)(x+8)+k\) 可因式分解成 \((x+a)(x+b)\)，其中 \(a\)、\(b\) 均為整數，則下列何者可能為 \(k\) 值？',['4','12','20','28'],4,r'\((x-3)(x+8)+k=x^2+5x-24+k\)；(A) \(x^2+5x-20\)、(B) \(x^2+5x-12\)、(C) \(x^2+5x-4\) 無法因式分解；(D) \(x^2+5x+4=(x+1)(x+4)\)。')
ch(r'【素養】下列何者是 \(3(x+2)(x-5)-2(x^2-2x-12)\) 的因式？',[r'\(x-6\)',r'\(x-3\)',r'\(x-2\)',r'\(x-1\)'],1,r'原式＝\(3(x^2-3x-10)-2(x^2-2x-12)=x^2-5x-6=(x+1)(x-6)\)，故選(A)。')
ch(r'【素養】利用十字交乘法作 \(x^2+px+q\) 因式分解的結果為 \((x+a)(x+b)\)，若 \(a<0\)，\(b<0\)，則點 \((p，q)\) 在坐標平面上的哪一個象限？',['第一象限','第二象限','第三象限','第四象限'],2,r'\(x^2+px+q=(x+a)(x+b)=x^2+(a+b)x+ab\)，\(\therefore p=a+b<0\)，\(q=ab>0\)，故點 \((p，q)\) 在第二象限。')
ch(r'【素養】已知 \(a\) 為正數，且 \(x^2-5x-a\) 可因式分解成 \((x-m)(x-n)\)，其中 \(m\)、\(n\) 均為整數，則 \(a\) 可能為下列何者？',[r'\(2\times3\times5\times7\)',r'\(2\times3\times7\times13\)',r'\(2\times5\times7\times17\)',r'\(2\times7\times11\times19\)'],2,r'\(x^2-5x-a\) 的一次項係數為 \(-5\)，\(m\)、\(n\) 兩數的絕對值差 5；(B) 當 \(m\)、\(n\) 分別為 \(2\times13=26\) 及 \(-3\times7=-21\) 符合，故選(B)。')
psg(r'王老先生有塊長方形土地，其面積為 \(15x^2-7x-2\) 平方單位，亦可表示為 \((ax+b)(cx+d)\)，其中 \(a\)、\(c\) 均為正整數，且 \(a<c\)。【素養題】')
ch(r'【素養】\((a+b)-(c+d)\) 之值為何？',['1','2','3','4'],1,r'\(15x^2-7x-2=(3x+2)(5x-1)\Rightarrow a=3\)，\(b=2\)，\(c=5\)，\(d=-1\)，故 \((a+b)-(c+d)=5-4=1\)。')
ch(r'【素養】若此塊長方形土地的長為 \(ax+b\)，寬為 \(cx+d\)，王老先生想將土地的三邊做圍欄，則下列何者可能是圍欄的總長度？',[r'\(8x+1\)',r'\(11x-3\)',r'\(13x\)',r'\(16x+2\)'],3,r'\(15x^2-7x-2=(3x+2)(5x-1)\)，圍欄的總長度可能為 ① \(2(3x+2)+(5x-1)=11x+3\)；② \((3x+2)+2(5x-1)=13x\)，故選(C)。')
endp()

sec('第10回 2-2～3-2 複習')
ch(r'下列何者不是多項式 \((x+5)(x-5)\) 的因式？',[r'\(5+x\)',r'\(2x-10\)',r'\(x^2-10\)',r'\(x^2-25\)'],3,r'\((x+5)(x-5)=x^2-25\)；(C) \((x^2-25)\div(x^2-10)\) 不能整除，\(\therefore x^2-10\) 不是因式。')
ch(r'如附圖，\(10-2\sqrt{5}\) 在數線上的位置應在哪兩點之間？（\(A\)、\(B\)、\(C\)、\(D\)、\(E\) 分別為 4、5、6、7、8）',[r'\(A\) 點和 \(B\) 點',r'\(B\) 點和 \(C\) 點',r'\(C\) 點和 \(D\) 點',r'\(D\) 點和 \(E\) 點'],2,r'\(2\sqrt{5}=\sqrt{20}=4.\cdots\Rightarrow10-2\sqrt{5}=5.\cdots\)，故選(B)。',img=(19,370,630,510,675))
ch(r'【素養】計算 \(\sqrt{8}-\sqrt{50}+6\sqrt{5}+3\sqrt{2}-\sqrt{125}\) 之值為何？',['0',r'\(\sqrt{2}\)',r'\(\sqrt{5}\)',r'\(5\sqrt{2}-\sqrt{5}\)'],3,r'原式＝\(2\sqrt{2}-5\sqrt{2}+6\sqrt{5}+3\sqrt{2}-5\sqrt{5}=\sqrt{5}\)。')
ch(r'【素養】若 \(a=\sqrt{3}-\sqrt{2}\)，則 \(-(a+2)(a-2)\) 之值為何？',[r'\(-9+2\sqrt{6}\)',r'\(-1+2\sqrt{6}\)',r'\(1-2\sqrt{6}\)','－1'],2,r'\(-(a+2)(a-2)=4-a^2=4-(\sqrt{3}-\sqrt{2})^2=4-(5-2\sqrt{6})=-1+2\sqrt{6}\)。')
ch(r'【素養】利用十字交乘法作多項式 \(A\) 的因式分解，過程如附圖（\(3x\) 與 \(-1\)、\(-x\) 與 \(+1\)，\(x+3x=4x\)），則下列關於多項式 \(A\) 的敘述，何者正確？',[r'\(A\) 的二次項係數為 3',r'\(A\) 的常數項為 1',r'\(x+1\) 是 \(A\) 的因式',r'\(1-3x\) 是 \(A\) 的因式'],4,r'\(A=(3x-1)(-x+1)=-3x^2+4x-1\)，故選(D)。',img=(19,415,1245,510,1310))
ch('【素養】下列哪一個式子無法再作係數為整數的因式分解？',[r'\(x^2-18\)',r'\(x^2-81\)',r'\(x^2+5x+6\)',r'\(x^2+5x-6\)'],1,r'(B) \(x^2-81=(x+9)(x-9)\)；(C) \(x^2+5x+6=(x+2)(x+3)\)；(D) \(x^2+5x-6=(x-1)(x+6)\)。')
ch(r'【素養】已知 \(x-2\) 是 \(3x^2-x+k\) 的因式，則下列何者也是 \(3x^2-x+k\) 的因式？',[r'\(3x+5\)',r'\(3x-5\)',r'\(3x+2\)',r'\(x-2\)（重根）'],1,r'以長除法 \((3x^2-x+k)\div(x-2)\)，商為 \(3x+5\)，餘式 \(k+10=0\)，故選(A)。')
ch(r'【素養】如附圖，有甲、乙、丙三種不同大小的長方形圖卡（甲：邊長 \(x\) 的正方形；乙：長 \(x\)、寬 1；丙：邊長 1 的正方形）。用 2 張甲、12 張乙和 16 張丙可以緊密且不重疊的方式拼成一個大長方形。若大長方形的長為 \(2x+4\)，則寬為下列何者？',[r'\(x\)',r'\(x+2\)',r'\(x+4\)',r'\(x-6\)'],3,r'依題意知：\(2x^2+12x+16=(2x+4)(x+4)\)，故選(C)。',img=(19,800,475,1000,555))
psg(r'附圖是小花與小美利用數學設計生日密碼的經過。生日密碼設計規則：1. 將生日的日期寫成 \(abcd\)，例：1月20日→0120，10月2日→1002。2. 將 \((dx+c)(bx+a)\) 展開。小花：我的密碼是 \(6x^2+7x+2\)；小美：我的是 \(4x^2+2x\)。【素養題】')
ch('【素養】請問小花的生日為何？',['11 月 13 日','11 月 26 日','12 月 16 日','12 月 23 日'],4,r'\(6x^2+7x+2=(3x+2)(2x+1)\)，故小花的生日為 12 月 23 日或 23 月 12 日（不合）。',img=(19,550,820,1000,950))
ch('【素養】請問小美的生日有幾種可能？',['1','2','3','4'],3,r'\(4x^2+2x=x(4x+2)\Rightarrow\)1 月 24 日或 24 月 1 日（不合）；\(4x^2+2x=2x(2x+1)\Rightarrow\)2 月 12 日或 12 月 2 日，故有 3 種可能。',img=(19,550,820,1000,950))
endp()

sec('第11回 4-1 因式分解法解一元二次方程式')
ch('下列哪一個一元二次方程式的解不是重根？',[r'\((3x+5)^2=0\)',r'\(x^2-2x+1=0\)',r'\(x^2-9=0\)',r'\(4x^2+12x+9=0\)'],3,r'(C) \(x^2-9=0\Rightarrow(x+3)(x-3)=0\Rightarrow x=-3\) 或 \(x=3\)。')
ch(r'一元二次方程式 \(5x^2-8x-21=0\) 的兩個解之和為多少？',['1',r'\(1\dfrac{1}{5}\)',r'\(1\dfrac{2}{5}\)',r'\(1\dfrac{3}{5}\)'],4,r'\(5x^2-8x-21=0\Rightarrow(x-3)(5x+7)=0\Rightarrow x=3\) 或 \(x=-\dfrac{7}{5}\)，故兩個解之和＝\(3+\left(-\dfrac{7}{5}\right)=1\dfrac{3}{5}\)。')
ch(r'【素養】小靜解方程式 \((2x+1)(x+3)=(x+3)(x-1)\) 的步驟如下：步驟一：同除以 \(x+3\) 得 \(2x+1=x-1\)；步驟二：移項得 \(2x+1-(x-1)=0\)；步驟三：去括號得 \(2x+1-x+1=0\)；步驟四：解得 \(x=-2\)。請問從哪一個步驟開始發生錯誤？',['步驟一','步驟二','步驟三','步驟四'],1,r'步驟一：不可以同除以 \(x+3\)（會漏掉 \(x=-3\) 的解），故選(A)。')
ch(r'【素養】若 \(a\)、\(b\) 為一元二次方程式 \(2x^2-x-6=0\) 的兩解，則下列何數介於 \(a\)、\(b\) 之間？',['－4','－1','3','4'],2,r'\(2x^2-x-6=0\Rightarrow(x-2)(2x+3)=0\Rightarrow x=2\) 或 \(x=-\dfrac{3}{2}\)，故選(B)。')
ch(r'【素養】有關方程式 \((x+1)^2-(2x-3)^2=0\) 的敘述，下列何者正確？',['有一個解是奇數','有一個解大於 4','有一個解不是整數','兩個解之和小於 2'],3,r'\((x+1)^2-(2x-3)^2=0\Rightarrow(x+1+2x-3)(x+1-2x+3)=0\Rightarrow(3x-2)(-x+4)=0\Rightarrow x=\dfrac{2}{3}\) 或 4，故選(C)。')
ch('【素養】下列哪一個一元二次方程式的兩個解都是負數？',[r'\(x^2+x=0\)',r'\(3x^2+2x-1=0\)',r'\(x^2-2x-3=0\)',r'\(x^2+3x+2=0\)'],4,r'(A) \(x(x+1)=0\Rightarrow x=0\) 或 \(-1\)；(B) \((3x-1)(x+1)=0\Rightarrow x=\dfrac{1}{3}\) 或 \(-1\)；(C) \((x-3)(x+1)=0\Rightarrow x=3\) 或 \(-1\)；(D) \((x+2)(x+1)=0\Rightarrow x=-2\) 或 \(-1\)，故選(D)。')
ch(r'【素養】已知 \(x\) 的一元二次方程式 \(x^2-36x+p=0\) 的兩個解皆為質數，則下列何者不可能是 \(p\) 的值？',['155','275','299','323'],2,r'(A) \(155=5\times31\)；(B) \(275=25\times11\)（25 不是質數）；(C) \(299=23\times13\)；(D) \(323=17\times19\)，故選(B)。')
ch(r'【素養】已知 \(x\) 的一元二次方程式 \(x^2-x-b=0\) 的兩個解皆為整數，且 \(b\) 為正整數，則 \(b\) 可能為下列何者？',[r'\(2\times3\times5\times11\)',r'\(2\times3\times7\times11\)',r'\(2\times5\times7\times11\)',r'\(3\times5\times7\times11\)'],2,r'兩解之差需為 1：(A) \(3\times5-2\times11=-7\neq-1\)；(B) \(3\times7-2\times11=-1\)；(C) \(2\times11-5\times7=-13\neq-1\)；(D) \(3\times11-5\times7=-2\neq-1\)，故選(B)。')
psg(r'甲、乙兩生同解一元二次方程式 \(x^2+mx+n=0\)，其中 \(m\)、\(n\) 皆為整數。若甲看錯 \(m\)，解出的兩個解為 \(-1\) 與 \(-6\)；乙看錯 \(n\)，解出的兩個解為 7 與 \(-2\)，除此之外，兩人並無其他計算上的錯誤。【素養題】')
ch(r'【素養】請問 \(m+n\) 之值為何？',['－7','－1','1','7'],3,r'甲：\((x+1)(x+6)=x^2+7x+6=0\Rightarrow n=6\)；乙：\((x-7)(x+2)=x^2-5x-14=0\Rightarrow m=-5\)，故 \(m+n=(-5)+6=1\)。')
ch('【素養】此一元二次方程式正確的兩個解為何？',['2 與 3','2 與 4','1 與 －3','－3 與 4'],1,r'\(x^2-5x+6=0\Rightarrow(x-2)(x-3)=0\Rightarrow x=2\) 或 \(x=3\)。')
endp()

sec('第12回 4-2 配方法與公式解')
ch(r'品豪利用配方法解一元二次方程式 \(3x^2-6x+96=0\) 的過程如下：步驟一：兩邊同除以 3 得 \(x^2-2x+32=0\)；步驟二：移項並同時加 1 得 \(x^2-2x+1=-32+1\)；步驟三：化簡得 \((x-1)^2=-31\)；步驟四：解得 \(x=1\pm\sqrt{31}\)。請問從哪一個步驟開始發生錯誤？',['步驟一','步驟二','步驟三','步驟四'],4,r'由步驟三：\((x-1)^2=-31<0\Rightarrow\) 步驟四：方程式無解，故選(D)。')
ch(r'小綺利用配方法解一元二次方程式 \(4x^2-5x-3=0\) 的過程如下：\(x^2-\dfrac{5}{4}x=\dfrac{3}{4}\Rightarrow x^2-\dfrac{5}{4}x+a=\dfrac{3}{4}+a\Rightarrow(x-b)^2=c\Rightarrow x-b=\pm\sqrt{c}\Rightarrow x=b\pm\sqrt{c}\)，則 \(a+b+c\) 之值為何？',[r'\(\dfrac{35}{16}\)',r'\(\dfrac{69}{32}\)',r'\(\dfrac{17}{8}\)',r'\(\dfrac{129}{64}\)'],2,r'\(a=\left(\dfrac{5}{8}\right)^2=\dfrac{25}{64}\)，\(b=\dfrac{5}{8}\)，\(c=\dfrac{3}{4}+\dfrac{25}{64}=\dfrac{73}{64}\)，故 \(a+b+c=\dfrac{25+40+73}{64}=\dfrac{138}{64}=\dfrac{69}{32}\)。')
ch(r'【素養】若 \(x=\dfrac{-7+\sqrt{61}}{6}\) 為方程式 \(3x^2+ax-1=0\) 的一個解，則 \(a\) 之值為何？',['－7','7','9','11'],2,r'\(x=\dfrac{-7+\sqrt{61}}{6}\Rightarrow6x+7=\sqrt{61}\Rightarrow(6x+7)^2=61\Rightarrow36x^2+84x+49=61\Rightarrow3x^2+7x-1=0\)，故 \(a=7\)。')
ch('【素養】下列哪一個一元二次方程式無解？',[r'\(9x^2+2x-6=0\)',r'\(6x^2-7x+3=0\)',r'\(x^2-8x-20=0\)',r'\(-3x^2-x+2=0\)'],2,r'(A) \(2^2-4\times9\times(-6)=4+216=220>0\)；(B) \((-7)^2-4\times6\times3=49-72=-23<0\)；(C) \((-8)^2-4\times1\times(-20)=64+80=144>0\)；(D) \((-1)^2-4\times(-3)\times2=1+24=25>0\)，故選(B)。')
ch(r'【素養】若 \(a\) 為方程式 \((x-\sqrt{17})^2=100\) 的一個解，\(b\) 為方程式 \((y-4)^2=17\) 的一個解，且 \(a\)、\(b\) 都是正數，則 \(a-b\) 之值為何？',['5',r'\(10-\sqrt{17}\)','6',r'\(\sqrt{83}\)'],3,r'\(a=\sqrt{17}+10\)，\(b=4+\sqrt{17}\)，故 \(a-b=\sqrt{17}+10-4-\sqrt{17}=6\)。')
ch(r'【素養】關於方程式 \(88(x-2)^2=95\) 的兩個解，下列敘述何者正確？',['兩個解都小於 0','兩個解都大於 2','一個解小於 1，另一個解大於 3','一個解小於 －2，另一個解大於 2'],3,r'\(88(x-2)^2=95\Rightarrow(x-2)^2\approx1.08\Rightarrow x=2\pm\sqrt{1.08}\approx3.\cdots\) 或 \(0.\cdots\)，故選(C)。')
ch(r'【素養】已知 \(m\) 為正整數，若方程式 \(4x^2-mx+3=0\) 無解，則 \(m\) 的所有可能值之和為多少？',['6','10','15','21'],4,r'已知 \(4x^2-mx+3=0\) 無解，表示其判別式小於 0，故 \((-m)^2-4\times4\times3<0\Rightarrow m^2<48\)，又 \(m\) 為正整數 \(\Rightarrow m=1\)、2、3、4、5、6，故所求＝21。')
ch(r'【素養】若方程式 \((x-2)(2x+3)=17\) 的負根為 \(a\)，且 \(\sqrt{185}\approx13.6\)，則 \(a\) 的範圍為何？',[r'\(-2<a<-1\)',r'\(-3<a<-2\)',r'\(-4<a<-3\)',r'\(-5<a<-4\)'],3,r'\((x-2)(2x+3)=17\Rightarrow2x^2-x-23=0\)，\(a=\dfrac{1-\sqrt{185}}{4}\approx\dfrac{1-13.6}{4}=-3.15\)，故選(C)。')
psg(r'有一個一元二次方程式 \(9x^2+bx+c=0\)，其中 \(b\)、\(c\) 皆為整數，小強利用配方法求解，本應在等號兩邊同加 9，即可將等號左邊配成完全平方式，但小強將 \(+c\) 看成 \(-c\)，所以同加上 23，此外沒有其他的錯誤。【素養題】')
ch('【素養】請問原一元二次方程式的常數項為何？',['7','16','－7','－16'],1,r'\(c+9=-c+23\Rightarrow2c=14\Rightarrow c=7\)。')
ch('【素養】此一元二次方程式的解不可能為下列何者？',[r'\(-\dfrac{5}{3}\)',r'\(-\dfrac{1}{3}\)',r'\(\dfrac{1}{3}\)',r'\(\dfrac{7}{3}\)'],1,r'原一元二次方程式為 \(9x^2+bx+7=0\Rightarrow9x^2+bx+16=9\)；① \(b>0\)，\((3x+4)^2=9\Rightarrow x=-\dfrac{1}{3}\) 或 \(-\dfrac{7}{3}\)；② \(b<0\)，\((3x-4)^2=9\Rightarrow x=\dfrac{7}{3}\) 或 \(\dfrac{1}{3}\)，故選(A)。')
endp()

sec('第13回 4-3 應用問題')
ch(r'銘暘想在果園中種 600 棵楊桃樹，每行所種的棵數比行數的 2 倍少 10。假設共種 \(x\) 行，依題意可得一元二次方程式為 \(x^2+ax+b=0\)，則 \(a+b\) 之值為何？',['305','295','－295','－305'],4,r'\(x(2x-10)=600\Rightarrow x^2-5x-300=0\)，\(\therefore a=-5\)，\(b=-300\)，故 \(a+b=-305\)。')
ch(r'小曄用長為 \(x\) 公分的原子筆去量一張長方形的紙，發現紙的長比原子筆的兩倍長少 1 公分，寬比原子筆的長多 2 公分。已知紙的面積為 3000 平方公分，則依題意可得下列哪一個一元二次方程式？',[r'\((x-2)(2x+1)=3000\)',r'\((x+2)(2x-1)+3000=0\)',r'\(2x^2-3x=3002\)',r'\(2x^2+3x-3002=0\)'],4,r'長方形紙的長為 \((2x-1)\) 公分，寬為 \((x+2)\) 公分，可列式為 \((2x-1)(x+2)=3000\Rightarrow2x^2+3x-3002=0\)，故選(D)。')
ch('【素養】已知父子兩人年齡相差 42 歲，5 年後，兒子年齡的平方剛好是爸爸的年齡，則今年父子兩人的年齡和為多少歲？',['45','46','47','48'],2,r'設今年兒子 \(x\) 歲，爸爸 \((x+42)\) 歲，\((x+5)^2=(x+42)+5\Rightarrow x^2+9x-22=0\Rightarrow(x-2)(x+11)=0\Rightarrow x=2\) 或 \(-11\)（不合），故所求＝\(2+(2+42)=46\)（歲）。')
ch('【素養】如附圖，若□代表同一個正整數，且 甲＋乙＋丙＋丁＝64（□＋□＝甲，□－□＝乙，□×□＝丙，□÷□＝丁），則下列何者錯誤？',['甲＝14','乙＝0','丙＝64','丁＝1'],3,r'設□＝\(x\)，則甲＝\(2x\)，乙＝0，丙＝\(x^2\)，丁＝1，\(2x+0+x^2+1=64\Rightarrow x^2+2x-63=0\Rightarrow(x-7)(x+9)=0\Rightarrow x=7\) 或 \(-9\)（不合），甲＝14，丙＝49，故選(C)。',img=(25,410,905,515,1035))
ch('【素養】已知一長方形紙片的長比寬多 3 公分，在此長方形紙片切下一個面積最大的正方形。若切下的面積比剩下的面積多 54 平方公分，則原長方形紙片的周長為多少公分？',['36','42','48','56'],2,r'設長方形的寬為 \(x\) 公分，則長為 \((x+3)\) 公分，\(x^2-3x=54\Rightarrow x^2-3x-54=0\Rightarrow(x-9)(x+6)=0\Rightarrow x=9\) 或 \(-6\)（不合），故所求＝\((9+9+3)\times2=42\)（公分）。')
ch('【素養】已知三個連續正偶數的平方和為 308，則此三個連續正偶數的和是多少？',['30','32','34','36'],1,r'設此三個連續偶數為 \(x-2\)、\(x\)、\(x+2\)，\((x-2)^2+x^2+(x+2)^2=308\Rightarrow3x^2=300\Rightarrow x=\pm10\)（負不合），故所求＝\(3x=30\)。')
ch('【素養】英俊和美男響應愛心捐款，英俊捐出的錢數比美男捐出錢數的 2 倍多 4 元。若英俊再多捐 20 元，則英俊捐出的錢數是美男捐出的錢數的平方，則原先英俊捐出的錢數比美男捐出的錢數多幾元？',['10','18','26','34'],1,r'設美男捐出 \(x\) 元，則英俊捐出 \((2x+4)\) 元，\(x^2=2x+4+20\Rightarrow x^2-2x-24=0\Rightarrow(x-6)(x+4)=0\Rightarrow x=6\) 或 \(-4\)（不合），故所求＝\(2\times6+4-6=10\)（元）。')
ch('【素養】某水果商買進蘋果若干個，全部裝在現有的盒子中，盒子數量恰好比每盒內的蘋果數多 7。若每盒少裝 2 個蘋果，則盒子數量為盒內蘋果數的 2 倍還多 5，且還剩 2 個蘋果沒裝進盒子。請問水果商買進多少個蘋果？',['150','160','170','180'],3,r'設一盒裝 \(x\) 個，則盒子有 \((x+7)\) 個；\(x(x+7)=(x-2)[2(x-2)+5]+2\Rightarrow x^2+7x=2x^2-3x\Rightarrow x^2-10x=0\Rightarrow x=0\)（不合）或 10，故買進蘋果 \(10\times(10+7)=170\)（個）。')
psg('營養師提供三種利用身高（公尺）推估目標體重（公斤）的算法，如附表：算法①：女生 身高×身高×21，男生 身高×身高×22；算法②：女生 (100×身高－70)×0.6，男生 (100×身高－80)×0.7；算法③：女生 (100×身高－160)×0.5＋52，男生 (100×身高－170)×0.6＋62。【素養題】')
ch('【素養】小謙的身高為 180 公分，則使用算法③算出他的目標體重為多少公斤？',['65','68','70','72'],2,r'\((100\times1.8-170)\times0.6+62=68\)（公斤）。',img=(25,550,615,995,735))
ch(r'【素養】小芸的身高為 \(x\) 公尺，其中 \(x>1.5\)。若她使用算法①與算法②算出的目標體重會相同，則 \(x\) 在下列哪一個範圍？（\(\sqrt{2}\approx1.414\)）',[r'\(1.60<x\leq1.61\)',r'\(1.61<x\leq1.62\)',r'\(1.62<x\leq1.63\)',r'\(1.63<x\leq1.64\)'],4,r'\(21x^2=(100x-70)\times0.6\Rightarrow21x^2-60x+42=0\Rightarrow7x^2-20x+14=0\Rightarrow x=\dfrac{10\pm\sqrt{2}}{7}\Rightarrow x=1.63\cdots\) 或 \(1.22\cdots\)（不合），故選(D)。',img=(25,550,615,995,735))
endp()

sec('第14回 第5章 統計資料處理')
ch('附表為某校七年孝班 40 位學生數學成績的次數分配表，則成績不及格（未滿 60 分）的人數占全班的百分比為多少？',['10%','12.5%','15%','17.5%'],2,r'不及格的有 \(2+3=5\)（人），所求＝\(\dfrac{5}{40}\times100\%=12.5\%\)。',img=(27,325,400,505,600))
ch(r'附表為某公司 200 名職員年齡的次數分配表，其中 34～40 歲及 46～52 歲的次數因汙損而無法辨識。若 34～40 歲、46～52 歲職員人數的相對次數分別為 \(a\%\)、\(b\%\)，則 \(a+b\) 之值為何？',['10','45','55','99'],3,r'34～40 歲及 46～52 歲共有 \(200-(6+40+42+2)=110\)（人），故 \(a+b=(110\div200)\times100=55\)。',img=(27,325,610,505,818))
ch(r'【素養】附表是某校九年二班數學成績的累積次數分配表，則下列敘述何者錯誤？',[r'\(A=8\)，\(B=21\)',r'\(B=21\)，\(C=35\)','全班共有 35 人','成績不及格（未滿 60 分）的有 10 人'],4,r'\(B=11+10=21\)，\(A=29-21=8\)，\(C=29+6=35\)（全班人數），不及格的有 \(4+7+10=21\)（人），故選(D)。',img=(27,285,890,505,1088))
ch('【素養】附圖是蘭宜國中九年級第一次段考數學成績的累積相對次數分配折線圖，則成績及格（滿 60 分）的人數占九年級的百分比為多少？',['60%','50%','40%','20%'],1,r'所求＝\(100\%-40\%=60\%\)。',img=(27,285,1095,510,1265))
ch(r'【素養】老師將班上同學的某次段考數學成績分成四組，並將資料記錄於附表。關於 \(a\)、\(b\)、\(c\)、\(d\) 的值，下列哪一個選項正確？',[r'\(a=10\)',r'\(b=35\)',r'\(c=65\)',r'\(d=75\)'],4,r'全班有 \(2\div10\%=20\)（人），\(a=20-(2+9+4)=5\)，\(b=100-(10+45+20)=25\)，\(c=45+10=55\)，\(d=20+c=20+55=75\)。',img=(27,130,1395,512,1518))
ch('【素養】附圖為某班數學成績的相對次數分配折線圖。若 90～100 分這一組有 2 人，則 40～50 分這一組有多少人？',['3','4','5','6'],1,r'全班有 \(2\div5\%=40\)（人），所求＝\(40\times7.5\%=3\)（人）。',img=(27,825,322,1008,465))
ch('【素養】附表是八年三班學生某次數學小考成績的次數分配表。若 50～60 分的人數占全班的 16%，60～70 分的人數占全班的 20%，則全班共有多少人？',['20','25','30','40'],2,r'其他各組共 \(3+4+4+3+2=16\)（人），占全班 \(100\%-16\%-20\%=64\%\)，故全班有 \(16\div64\%=25\)（人）。',img=(27,830,470,1000,665))
ch('【素養】附圖為八年一班第三次段考數學成績的累積相對次數分配折線圖。若及格（滿 60 分）的人數有 11 人，則下列敘述何者正確？',['全班有 30 人','60～80 分有 8 人','不及格的有 9 人','90～100 分有 2 人'],3,r'(A) \(100\%-45\%=55\%\)，\(11\div55\%=20\)（人）；(B) \((75-45)\%\times20=6\)（人）；(C) \(20-11=9\)（人）；(D) \((100-85)\%\times20=3\)（人），故選(C)。',img=(27,780,668,1005,812))
psg('捷運公司統計 1 月及 2 月旅客當月使用悠遊卡搭乘捷運的累積相對次數分配折線圖與當月常客搭乘次數優惠方案表（搭乘 10～20 次回饋 10%、20～30 次 15%、30～40 次 20%、40～50 次 25%、50 次以上 30%），如附圖。【素養題】')
ch('【素養】1 月使用悠遊卡搭乘 30 次以上（含）的百分比為多少？',['42%','50%','54%','58%'],1,r'\(100\%-58\%=42\%\)。',img=(27,545,893,1000,1118))
ch('【素養】2 月獲得回饋金 20% 的旅客占 2 月旅客的百分比為多少？',['10%','15%','17%','18%'],4,r'即搭乘 30～40 次的旅客，故占 \(68\%-50\%=18\%\)。',img=(27,545,893,1000,1118))
endp()

sec('第15回 4-1～第5章 複習')
ch(r'若 \(x=0\) 為方程式 \(2x^2-5mx+(m-2)=0\) 的一個解，則另一個解為何？',['3','4','5','6'],3,r'\(x=0\) 代入得 \(m-2=0\Rightarrow m=2\)；\(m=2\) 代入得 \(2x^2-10x=0\Rightarrow x(x-5)=0\Rightarrow x=0\) 或 \(x=5\)，故選(C)。')
ch('附圖是某班第一次段考國文成績的累積相對次數分配折線圖。若有 6 人未滿 60 分，則全班共有多少人？',['30','40','42','43'],1,r'未滿 60 分占 20%，\(6\div20\%=30\)（人）。',img=(29,300,555,510,716))
ch(r'【素養】利用配方法將 \(4x^2-4x-17=0\) 化成 \(4(x+p)^2=q\) 的形式，則 \(p\times q\) 之值為何？',['4','9','－4','－9'],4,r'原式 \(\Rightarrow4x^2-4x+1=17+1\Rightarrow(2x-1)^2=18\Rightarrow4\left(x-\dfrac{1}{2}\right)^2=18\)，故 \(p=-\dfrac{1}{2}\)，\(q=18\)，\(p\times q=-9\)。')
ch('【素養】如附圖，寒斌將一個邊長為 20 公分的正方形，截去四個腰長都一樣的等腰直角三角形。若灰色部分的面積為 350 平方公分，則截去的等腰直角三角形的腰長為多少公分？',['5','6','7','8'],1,r'設截去的等腰直角三角形腰長為 \(x\) 公分，\(20^2-4\times\dfrac{1}{2}x^2=350\Rightarrow x^2=25\Rightarrow x=\pm5\)（負不合）。',img=(29,425,925,510,1010))
ch(r'若 1 和 －1 是方程式 \(x^2+px+q=0\) 的兩個解，則下列何者正確？',[r'\(p=0\)',r'\(p=-1\)',r'\(q=0\)',r'\(q=1\)'],1,r'\(x=1\)、\(-1\) 分別代入得 \(1+p+q=0\)、\(1-p+q=0\)，兩式相加得 \(2+2q=0\Rightarrow q=-1\)，代回得 \(p=0\)，故選(A)。')
ch(r'【素養】關於方程式 \((x+3)^2=(-5x-3)^2\) 的解，下列敘述何者正確？',['有兩正解','有兩負解','有一正解及一負解','有一負解及一解為零'],4,r'原式 \(\Rightarrow x^2+6x+9=25x^2+30x+9\Rightarrow24x^2+24x=0\Rightarrow24x(x+1)=0\Rightarrow x=0\) 或 \(x=-1\)，故選(D)。')
ch(r'【素養】若 \(x\) 的一元二次方程式 \(3x^2+5x-k+2=0\) 無解，則 \(k\) 的最大整數值為何？',['1','0','－1','－2'],3,r'判別式 \(5^2-4\times3\times(-k+2)<0\Rightarrow1+12k<0\Rightarrow k<-\dfrac{1}{12}\)，故 \(k\) 的最大整數值為 －1，選(C)。')
ch(r'【素養】附表是甲班學生身高的部分統計資料，則 \(b+c\) 之值為何？',['36','38','40','42'],2,r'設甲班有 \(x\) 人，\(\dfrac{26}{x}=65\%\Rightarrow x=40\)，\(\dfrac{c}{40}=80\%\Rightarrow c=32\)，\(b=32-26=6\)，故 \(b+c=6+32=38\)。',img=(29,625,400,1000,512))
psg('附圖是小謙班上第一段考數學科成績的累積次數分配折線圖。【素養題】')
ch('【素養】若小謙的成績為 79 分，則他在班上的排名可能為下列哪一個名次？',['33','27','18','8'],4,r'未滿 80 分有 34 人，未滿 70 分有 24 人，全班 40 人，故 70～80 分的小謙名次在第 7～16 名，選(D)。',img=(29,545,625,1003,850))
ch('【素養】60～70 分這一組的相對次數為多少？',['5%','10%','50%','60%'],2,r'\(\dfrac{24-20}{40}\times100\%=10\%\)。',img=(29,545,625,1003,850))
endp()
